Could you make your example self-contained? i.e. one single file that<br>other people can simply compile (no need to add p &lt;- before<br>structure(), or wonder what is data[, c(3:4)], etc)<br><br>Regards,<br>Yihui<br>--<br>Yihui Xie &lt;<a href data-email-masked rel="nofollow">xiey...@gmail.com</a>&gt;<br>Web: <a href="http://yihui.name" target="_blank" rel="nofollow" data-saferedirecturl="https://www.google.com/url?hl=en-US&amp;q=http://yihui.name&amp;source=gmail&amp;ust=1792354966094000&amp;usg=AOvVaw3WFUTnnbV2sHJGfwkjpPTC">http://yihui.name</a><br><br><br>On Mon, Oct 26, 2015 at 3:15 PM, Mike Dylan &lt;<a href data-email-masked rel="nofollow">seanca...@gmail.com</a>&gt; wrote:<br>&gt; I am trying to run knitr and it seems to be taking a very long time to<br>&gt; complete.<br>&gt;<br>&gt; dput(p)<br>&gt;<br>&gt; structure(list(Hostname = structure(c(1L, 1L, 1L, 1L, 1L, 1L), .Label =<br>&gt; c(&quot;server101&quot;, &quot;server102&quot;, &quot;server103&quot;, &quot;server104&quot;, &quot;test101&quot;, &quot;app101d&quot;,<br>&gt; &quot;web25&quot;, &quot;web26&quot;, &quot;web111&quot;, &quot;web11&quot;, &quot;web123&quot;, &quot;tomcat101&quot;, &quot;tomcat103&quot;,<br>&gt; &quot;tomcat104&quot;), class = &quot;factor&quot;), Date = structure(c(1441373431, 1441372531,<br>&gt; 1441737938, 1441337431, 1441374331, 1441367131), class = c(&quot;POSIXct&quot;,<br>&gt; &quot;POSIXt&quot;), tzone = &quot;&quot;), Cpubusy = c(22, 21, 20, 28, 22, 20),<br>&gt; UsedPercentMemory = c(3L, 3L, 21L, 3L, 3L, 4L), App = structure(c(1L, 1L,<br>&gt; 1L, 1L, 1L, 1L), .Label = c(&quot;WEB&quot;, &quot;DB&quot;), class = &quot;factor&quot;), HA =<br>&gt; structure(c(1L, 1L, 1L, 1L, 1L, 1L), .Label = c(&quot;server3456&quot;, &quot;backup101&quot;,<br>&gt; &quot;ha123&quot;, &quot;No HA Host&quot;, &quot;No HA Host&quot;, &quot;server120&quot;, &quot;server234&quot;, &quot;server666&quot;,<br>&gt; &quot;No HA Host&quot;), class = &quot;factor&quot;), DR = structure(c(5L, 5L, 5L, 5L, 5L, 5L),<br>&gt; .Label = c(&quot;Cannot login to DR Host&quot;, &quot;dr101&quot;, &quot;dr345&quot;, &quot;dr444&quot;, &quot;dr5678&quot;,<br>&gt; &quot;No DR Host&quot;, &quot;drserver11&quot;, &quot;dr666&quot;, &quot;No HA Host&quot;, &quot;No HA Host&quot;, &quot;No HA<br>&gt; Host&quot;), class = &quot;factor&quot;)), .Names = c(&quot;Hostname&quot;, &quot;Date&quot;, &quot;Cpubusy&quot;,<br>&gt; &quot;UsedPercentMemory&quot;, &quot;App&quot;, &quot;HA&quot;, &quot;DR&quot;), row.names = c(NA, 6L), class =<br>&gt; &quot;data.frame&quot;)<br>&gt;<br>&gt; dput(c)<br>&gt;<br>&gt; structure(list(App = structure(c(1L, 2L, 2L, 2L, 2L, 1L), .Label = c(&quot;WEB&quot;,<br>&gt; &quot;APP&quot;), class = &quot;factor&quot;), Prod = structure(c(1L, 5L, 6L, 4L, 3L, 2L),<br>&gt; .Label = c(&quot;server101&quot;, &quot;server102&quot;, &quot;server104&quot;, &quot;server106&quot;, &quot;server107&quot;,<br>&gt; &quot;server109&quot;), class = &quot;factor&quot;), HA = structure(c(1L, 3L, 3L, 3L, 3L, 2L),<br>&gt; .Label = c(&quot;server3456&quot;, &quot;server3456&quot;, &quot;No HA Host&quot; ), class = &quot;factor&quot;), DR<br>&gt; = structure(c(1L, 2L, 2L, 2L, 2L, 3L ), .Label = c(&quot;dr5678&quot;, &quot;No DR Host&quot;,<br>&gt; &quot;No DR Host&quot;), class = &quot;factor&quot;)), .Names = c(&quot;App&quot;, &quot;Prod&quot;, &quot;HA&quot;, &quot;DR&quot;),<br>&gt; row.names = c(NA, 6L), class = &quot;data.frame&quot;)<br>&gt;<br>&gt; application&lt;-unique(c$App, drop=TRUE)<br>&gt; application&lt;-droplevels(application)<br>&gt;<br>&gt; metrics&lt;-unique(colnames(data[,c(3:4)]))<br>&gt; metrics&lt;-as.factor(metrics)<br>&gt; metrics&lt;-droplevels(metrics)<br>&gt;<br>&gt; env&lt;-unique(colnames(cmdb[,c(2:4)]))<br>&gt; env&lt;-as.factor(env)<br>&gt; env&lt;-droplevels(env)<br>&gt;<br>&gt; then run this code to pull data and put the charts on a pdf file:<br>&gt;<br>&gt; ```{r qplot,fig.width=10, fig.height=8, message=FALSE, results = &#39;asis&#39;,<br>&gt; echo=FALSE, warning=FALSE, fig.cap=&quot;long caption&quot;, fig.scap=&quot;short&quot;}<br>&gt;<br>&gt; library(ggplot2)<br>&gt; library(knitr)<br>&gt;<br>&gt; for (product in application){<br>&gt;   product&lt;-gsub(&quot;\(&quot;, &quot;_&quot;,product)<br>&gt;   product&lt;-gsub(&quot;\)&quot;, &quot;_&quot;,product)<br>&gt;   for(en in env){<br>&gt;<br>&gt;      tryCatch({<br>&gt;         mergedData &lt;- merge(pp, c, by.x=c(&quot;Hostname&quot;),by.y=en)<br>&gt;         cat(paste(product, en, &quot; - Environment&quot;))<br>&gt;         cat(&quot;
&quot;)<br>&gt;<br>&gt;         for(m in metrics){<br>&gt;<br>&gt;             p&lt;-ggplot(mergedData,aes(Date, m, group=Hostname,<br>&gt; colour=Hostname))+geom_line()+<br>&gt;               geom_smooth(method=&quot;lm&quot;, se=T, colour=&quot;blue&quot;)+<br>&gt;               facet_wrap(~Hostname)+theme_bw()+<br>&gt;               ggtitle(m)+<br>&gt;               theme(strip.background = element_rect(colour=&quot;blue&quot;,<br>&gt; fill=&quot;#b2d8ff&quot;),axis.text.x = element_text(angle = 30,hjust =<br>&gt; 1),plot.background = element_rect(size = 1, colour=&quot;black&quot;,linetype =<br>&gt; &quot;solid&quot;))+<br>&gt;               scale_fill_brewer(palette=&quot;RdYlGn&quot;)<br>&gt;               print(p)<br>&gt;               cat(&quot;
&quot;)<br>&gt;        }<br>&gt;      },error=function(e) {<br>&gt;         print(paste(product, &quot;does not have - &quot;, en, &quot;- Environment&quot;))<br>&gt;        print(&quot;
&quot;)<br>&gt;      })<br>&gt;   }<br>&gt; }<br>&gt; ```<br>&gt;<br>&gt; It is taking a very long time, not sure what the problem is?<br>&gt;<br>

